static class Registry {
    private final String name;

    Registry(String name) {
        this.name = name;
    }

    String name() {
        return name;
    }

    static class Entry {
        private final String key;
        private final int value;

        Entry(String key, int value) {
            this.key = key;
            this.value = value;
        }

        String key() {
            return key;
        }

        int value() {
            return value;
        }
    }
}
